; ---------------------------------------------------------------------------
; /* if changed, ITEMPLATE_END should be also changed accordingly */
; struct itemplate {
;    enum opcode     opcode;             /* the token, passed from "parser.c" */
;    int             operands;           /* number of operands */
;    opflags_t       opd[MAX_OPERANDS];  /* bit flags for operand types */
;    decoflags_t     deco[MAX_OPERANDS]; /* bit flags for operand decorators */
;    const uint8_t   *code;              /* the code it assembles to */
;    uint32_t        iflag_idx;          /* some flags referenced by index */
; };
;
; * this define is used to signify the end of an itemplate */
; #define ITEMPLATE_END {I_none,0,{0,},{0,},NULL,0}
;

; IDA
; ---
; itemplate       struc
;   opcode        dd ?
;   operands      dd ?
;   opd           dq 5 dup(?)
;   deco          dw 5 dup(?)
;   align4        dw ?
;   bytecode_ptr  dd ?        ; offset rva
;   iflag_idx     dd ?
;   align8        dd ?
; itemplate       ends

; NASM
; ----
; struc itemplate
;   .opcode:       resd 1
;   .operands:     resd 1
;   .opd:          resq 5
;   .deco:         resw 5
;   .align4:       resw 1
;   .bytecode_ptr: resd 1     ; offset rva
;   .iflag_idx:    resd 1
;   .align8:       resd 1  ; 8 byte alignment will not be used
; .size: 72 bytes (68 bytes will be used)
; endstruc

; insnsi.h
; --------------------------------------------------------
